  "firstMeeting.dodo": "隊長，快看這個！世紀大發現！",
  "firstMeeting.tia": "研究員，看見那個亮晶晶的東西了嗎？我能去撿嗎？",
  "firstMeeting.stella": "初次見面，前輩！今天的風路我已經全部讀好了。",
  "firstMeeting.meron": "那個，我是梅隆……想給你畫幅畫，能讓我看看你的臉嗎？",
  "firstMeeting.pachi": "喂，讓開！我在給老大開路。",
  "firstMeeting.maki": "先從診斷開始喵。別看我這樣，我可是醫生喵！",
  "firstMeeting.keris": "前輩，有想找的書嗎？我給你帶路。",
  "firstMeeting.delopi": "鏘鏘！這是你的鑰匙，研究員。",
  "firstMeeting.nodonia": "疼的時候要告訴我哦，小傢伙。我會替你擋下來的。",
  "firstMeeting.ella": "我會守住陣地。後方交給我。",
  "firstMeeting.mette": "只屬於你的舞臺，現在開幕。",
  "firstMeeting.deina": "我是黛依！這面牆還什麼都沒有呢？可以在這裡畫嗎？",
  "firstMeeting.maddy": "我是瑪蒂，研究員。這裡有點熱，能把冷氣開大些嗎？",
  "firstMeeting.terisa": "要是哪裡破了請告訴我……我來為您縫好，研究員大人。",
  "firstMeeting.parua": "好遠……好遠啊！全都看得見。",
  "firstMeeting.shute": "都說了不是那個！聽我指揮，我帶飛你。",
  "firstMeeting.morphe": "……管理員？來得正好。稍等……我把畫面調出來。",
  "firstMeeting.dian": "我會保護隊長的！……啊，克羅！希羅！過來！",
