  "relic.raitia-wind.squadNote": "殲滅的消耗性兵力。她們朝指向的方向一齊湧去填滿走廊，後面的直接踏過前面倒下的地方。",
  "relic.raitia-wind.researcherTitle": "研究員",
  "relic.raitia-wind.unlockRecord": "識別記錄211。確認隸屬於殲滅。是同樣穿著連帽睡衣的姐妹中繫著薄荷色絲帶的個體，抱著胳膊、緊閉著嘴站著。直到姐妹們湧向食物之後，它才勉強跟了過去，到了之後卻是啃動門齒最久的一個。從未觀察到它用門齒的聲音傳達過任何資訊。",
  "relic.raitia-wind.observation.originYear": "約200萬年前",
  "relic.raitia-wind.observation.restorationYear": "E.C. 2",
  "relic.raitia-wind.observation.lifeStage": "幼年",
  "relic.raitia-wind.observation.height": "0.94 m",
  "relic.raitia-wind.observation.weight": "21 kg",
  "relic.raitia-wind.passive.name": "冬眠",
  "relic.raitia-wind.passive.desc": "每場戰鬥一次，生命降至一半以下時，5秒內每秒恢復最大生命的3%。",
  "relic.raitia-wind.ferocity.name": "暴食",
  "relic.raitia-wind.basic.name": "門齒啃咬",
  "relic.raitia-wind.ultimate.name": "頰囊傾倒",
  "relic.raitia-wind.projectName": "ANNIHILATION SWARM — 過食個體群",
