  "relic.deina.origin": "恐爪龍",
  "relic.maddy.origin": "猛獁象",
  "relic.terisa.origin": "鐮刀龍",
  "relic.morphe.origin": "雙型齒翼龍",
  "relic.parua.origin": "副櫛龍",
  "relic.shute.origin": "劍龍",
